import { EventEmitter } from 'events';
import * as fs from 'fs';
import * as path from 'path';

interface DeviceConfig {
  deviceId: string;
  firmwareVersion: string;
  logPath: string;
  maxLogSize: number;
}

class LogEncoder {
  private static readonly SAFE_CHARS = /[\x20-\x7E]/;

  static encodeField(value: string): string {
    let encoded = '';
    for (let i = 0; i < value.length; i++) {
      const ch = value[i];
      if (this.SAFE_CHARS.test(ch) && ch !== '|') {
        encoded += ch;
      } else {
        encoded += `\\x${value.charCodeAt(i).toString(16).padStart(2, '0')}`;
      }
    }
    return encoded;
  }

  static formatLogEntry(timestamp: number, level: string, source: string, message: string): string {
    const ts = new Date(timestamp).toISOString();
    const encodedSource = this.encodeField(source);
    const encodedMessage = this.encodeField(message);
    return `${ts}|${level}|${encodedSource}|${encodedMessage}`;
  }
}

class DeviceLogger {
  private logBuffer: string[] = [];
  private flushInterval: NodeJS.Timer | null = null;
  private logStream: fs.WriteStream | null = null;
  private shuttingDown = false;

  constructor(private config: DeviceConfig) {
    // Sanitize deviceId to prevent path traversal when building the log file path.
    const safeDeviceId = DeviceLogger.sanitizeDeviceId(config.deviceId);
    const resolvedLogPath = path.resolve(config.logPath);
    const logFile = path.join(resolvedLogPath, `device_${safeDeviceId}.log`);
    // Defense-in-depth: ensure the resolved log file stays within the log directory.
    const resolvedLogFile = path.resolve(logFile);
    if (resolvedLogFile !== path.join(resolvedLogPath, `device_${safeDeviceId}.log`) ||
        !resolvedLogFile.startsWith(resolvedLogPath + path.sep)) {
      throw new Error('Invalid log file path');
    }
    this.logStream = fs.createWriteStream(resolvedLogFile, { flags: 'a' });
    this.flushInterval = setInterval(() => this.flush(), 5000);
  }

  private static sanitizeDeviceId(deviceId: string): string {
    // Allow only safe filename characters; reject anything that could enable traversal.
    const sanitized = (deviceId || '').replace(/[^A-Za-z0-9_-]/g, '_');
    return sanitized.length > 0 ? sanitized : 'unknown';
  }

  log(level: string, source: string, message: string): void {
    if (this.shuttingDown) return;
    const entry = LogEncoder.formatLogEntry(Date.now(), level, source, message);
    this.logBuffer.push(entry);
    if (this.logBuffer.length >= 50) {
      this.flush();
    }
  }

  private flush(): void {
    if (this.logBuffer.length === 0) return;
    const batch = this.logBuffer.splice(0);
    const output = batch.join('\n') + '\n';
    this.logStream?.write(output);
  }

  async gracefulShutdown(reason: string): Promise<void> {
    this.shuttingDown = true;
    if (this.flushInterval) {
      clearInterval(this.flushInterval);
    }
    // Log shutdown reason through the standard encoding path
    const shutdownEntry = this.formatShutdownEntry(reason);
    this.logBuffer.push(shutdownEntry);
    this.flush();
    return new Promise((resolve) => {
      this.logStream?.end(() => resolve());
    });
  }

  private formatShutdownEntry(reason: string): string {
    const ts = new Date().toISOString();
    // Use the same encoding as all other log entries
    const encodedReason = LogEncoder.encodeField(reason);
    return `${ts}|SHUTDOWN|firmware_core|${encodedReason}`;
  }
}

class FirmwareCore extends EventEmitter {
  private logger: DeviceLogger;
  private sensorData: Map<string, number> = new Map();
  private isRunning = false;

  constructor(private config: DeviceConfig) {
    super();
    this.logger = new DeviceLogger(config);
  }

  async initialize(): Promise<void> {
    this.isRunning = true;
    this.logger.log('INFO', 'firmware_core', `Device ${this.config.deviceId} initialized, fw=${this.config.firmwareVersion}`);
    this.setupSignalHandlers();
    this.emit('ready');
  }

  private setupSignalHandlers(): void {
    const shutdown = async (signal: string) => {
      if (!this.isRunning) return;
      this.isRunning = false;
      await this.logger.gracefulShutdown(`Signal received: ${signal}`);
      process.exit(0);
    };

    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));
  }

  processSensorReading(sensorId: string, value: number, metadata?: string): void {
    if (!this.isRunning) return;
    this.sensorData.set(sensorId, value);
    const msg = metadata 
      ? `Sensor ${sensorId}: ${value} [${metadata}]`
      : `Sensor ${sensorId}: ${value}`;
    this.logger.log('DATA', 'sensor_subsystem', msg);
  }

  async handleRemoteCommand(command: string, payload: Record<string, string>): Promise<void> {
    if (!this.isRunning) return;
    this.logger.log('INFO', 'remote_cmd', `Received command: ${command}`);

    switch (command) {
      case 'reboot':
        const rebootReason = payload.reason || 'remote_reboot';
        await this.logger.gracefulShutdown(rebootReason);
        break;
      case 'update_config':
        this.logger.log('INFO', 'remote_cmd', `Config update: ${JSON.stringify(payload)}`);
        break;
      case 'diagnostics':
        this.runDiagnostics();
        break;
      default:
        this.logger.log('WARN', 'remote_cmd', `Unknown command: ${command}`);
    }
  }

  private runDiagnostics(): void {
    const memUsage = process.memoryUsage();
    this.logger.log('INFO', 'diagnostics', `heap_used=${memUsage.heapUsed}, rss=${memUsage.rss}`);
  }
}

// Entry point
const config: DeviceConfig = {
  deviceId: process.env.DEVICE_ID || 'dev-001',
  firmwareVersion: '2.4.1',
  logPath: process.env.LOG_PATH || '/var/log/iot',
  maxLogSize: 10 * 1024 * 1024
};

const firmware = new FirmwareCore(config);
firmware.initialize().catch(console.error);

export { FirmwareCore, DeviceLogger, LogEncoder, DeviceConfig };
